let joy={active:false,id:null,x:0,y:0,dx:0,dy:0};const stick=$('stick'),knob=$('knob');
function joyStart(e){const r=stick.getBoundingClientRect();joy.active=true;joy.id=e.pointerId;joy.x=r.left+r.width/2;joy.y=r.top+r.height/2;stick.setPointerCapture(e.pointerId);joyMove(e)}function joyMove(e){if(!joy.active||e.pointerId!==joy.id)return;let dx=e.clientX-joy.x,dy=e.clientY-joy.y,l=Math.hypot(dx,dy),max=39;if(l>max){dx*=max/l;dy*=max/l}joy.dx=dx/max;joy.dy=dy/max;knob.style.transform=`translate(${dx}px,${dy}px)`}function joyEnd(e){if(e.pointerId!==joy.id)return;joy.active=false;joy.dx=joy.dy=0;knob.style.transform=''}stick.addEventListener('pointerdown',joyStart);stick.addEventListener('pointermove',joyMove);stick.addEventListener('pointerup',joyEnd);stick.addEventListener('pointercancel',joyEnd);
const ENEMY_TYPES={chaser:{hp:30,speed:57,damage:12,r:12,color:'#ff718e',xp:1,coins:1},fast:{hp:17,speed:100,damage:9,r:9,color:'#ffd36d',xp:1,coins:1},tank:{hp:100,speed:29,damage:21,r:19,color:'#b699ff',xp:3,coins:3},shooter:{hp:37,speed:39,damage:8,r:13,color:'#68e0db',xp:2,coins:2},exploder:{hp:25,speed:67,damage:23,r:12,color:'#ff9d59',xp:1,coins:2},boss:{hp:1350,speed:34,damage:28,r:34,color:'#ff427e',xp:18,coins:25}};
function spawnEnemy(type){let a=rand(0,Math.PI*2),dist=Math.max(W,H)*.65+50,x=game.player.x+Math.cos(a)*dist,y=game.player.y+Math.sin(a)*dist;const def=ENEMY_TYPES[type],scale=1+(game.wave-1)*.19+(type==='boss'?0:game.time*.004);game.enemies.push({type,x,y,r:def.r,hp:def.hp*scale,maxHp:def.hp*scale,speed:def.speed*(1+(game.wave-1)*.025),damage:def.damage*(1+(game.wave-1)*.08),color:def.color,xp:def.xp,coins:def.coins,cool:rand(.8,2),flash:0,knock:0,phase:rand(0,5)})}
function emit(x,y,color,n=5,speed=100){for(let i=0;i<n;i++){let a=rand(0,Math.PI*2),v=rand(speed*.35,speed);game.particles.push({x,y,vx:Math.cos(a)*v,vy:Math.sin(a)*v,r:rand(1.5,4),life:rand(.18,.55),max:.55,color})}}
function floatText(x,y,text,color='#fff',size=12){game.texts.push({x,y,text,color,size,life:.72,max:.72})}
function takeDamage(amount){const p=game.player;if(p.invuln>0)return;p.hp-=Math.max(1,amount-p.armor*1.6);p.invuln=.48;game.shake=8;emit(p.x,p.y,'#ff738b',12,170);sound(130,.12,'sawtooth',.04);if(p.hp<=0){p.hp=0;updateHud();gameOver(false)}}
function grantXp(n){const p=game.player;p.xp+=n;while(p.xp>=p.xpNeed){p.xp-=p.xpNeed;p.level++;p.xpNeed=Math.ceil(p.xpNeed*1.34+1);levelUp()}}
function levelUp(){if(state!=='playing')return;state='levelup';const opts=[...UPGRADES].sort(()=>Math.random()-.5).slice(0,3);showPanel(`<div class="eyebrow">Level ${game.player.level} · pick one upgrade</div><div class="title" style="font-size:clamp(30px,6vw,46px)">LEVEL <span class="accent">UP!</span></div><div class="grid">${opts.map((u,i)=>`<div class="pick" data-up="${i}"><div class="emoji">${u.icon}</div><h3>${u.name}</h3><p>${u.desc}</p></div>`).join('')}</div>`);panel.querySelectorAll('[data-up]').forEach((el,i)=>el.onclick=()=>{opts[i].apply(game.player);sound(700,.12,'triangle');state='playing';overlay.classList.add('hidden');updateHud()})}
function waveShop(){if(game.wave>=10){gameOver(true);return}state='shop';game.wave++;game.waveTime=30;game.spawn=1;game.bossSpawned=false;game.rerolls=0;game.reroll=6+game.wave*2;game.shopItems=makeShop();renderShop()}
function makeShop(){const pool=[...SHOP].sort(()=>Math.random()-.5);return pool.slice(0,4)}
