panel.querySelectorAll('[data-buy]').forEach(b=>b.onclick=()=>buyItem(+b.dataset.buy));$('lock').onclick=()=>{game.lock=!game.lock;renderShop()};$('reroll').onclick=()=>{if(p.coins<game.reroll){showToast('Not enough coins');return}p.coins-=game.reroll;game.reroll=Math.ceil(game.reroll*1.55);game.rerolls++;if(!game.lock)game.shopItems=makeShop();sound(540,.08);renderShop()};$('next').onclick=()=>{state='playing';overlay.classList.add('hidden');updateHud()}}
function findWeapon(id){return game.player.weapons.find(w=>w.id===id)}

