function findWeapon(id){return game.player.weapons.find(w=>w.id===id)}
function makeShop(){let pool=[...SHOP].sort(()=>Math.random()-.5).slice(0,3);let ids=Object.keys(WEAPONS).filter(id=>!findWeapon(id));if(ids.length&&Math.random()<.72){const id=choice(ids),w=WEAPONS[id];pool.push({weapon:true,id,name:w.name,icon:w.icon,desc:w.desc+' New weapon.',price:24+Math.floor(Math.random()*9)})}else pool.push([...SHOP].sort(()=>Math.random()-.5)[0]);return pool.sort(()=>Math.random()-.5)}
function buyItem(i){const item=game.shopItems[i],p=game.player;if(!item||p.coins<item.price){showToast('Not enough coins');return}p.coins-=item.price;if(item.weapon){const own=findWeapon(item.id);if(own){own.level++;own.cool=0;showToast(`${item.name} upgraded to Lv ${own.level}`)}else{p.weapons.push({id:item.id,level:1,cool:0});showToast(`${item.name} equipped!`)}}else item.apply(p);sound(660,.1,'triangle');emit(p.x,p.y,'#ffd36d',8,90);updateHud();renderShop()}
function updateHud(){if(!game)return;let p=game.player;$('hptext').textContent=`♥ ${Math.ceil(p.hp)} / ${Math.ceil(p.maxHp)}`;$('hpbar').style.width=`${clamp(p.hp/p.maxHp*100,0,100)}%`;$('leveltext').textContent=`LV ${p.level}`;$('xpbar').style.width=`${clamp(p.xp/p.xpNeed*100,0,100)}%`;$('statline').textContent=`DMG ${Math.round(p.damage)} · ARM ${Math.round(p.armor)} · SPD ${Math.round(p.speed)}`;$('wavetext').textContent=`${game.wave}/10`;$('timertext').textContent=`${Math.ceil(game.waveTime)}s`;$('cointext').textContent=p.coins}
function targetNearest(){const p=game.player;let best=null,bd=Infinity;for(const e of game.enemies){let d=(e.x-p.x)**2+(e.y-p.y)**2;if(d<bd){bd=d;best=e}}return best}
function fireWeapons(dt){const p=game.player,target=targetNearest();for(const slot of p.weapons){slot.cool-=dt;if(slot.cool>0||!target)continue;const w=WEAPONS[slot.id],level=slot.level,dx=target.x-p.x,dy=target.y-p.y,dist=Math.hypot(dx,dy),angle=Math.atan2(dy,dx);if(w.type==='melee'){if(dist<w.range+target.r){const hits=game.enemies.filter(e=>Math.hypot(e.x-p.x,e.y-p.y)<w.range+e.r&&(Math.cos(Math.atan2(e.y-p.y,e.x-p.x)-angle)>.12));hits.forEach(e=>hitEnemy(e,w.damage*p.damage/10*(1+(level-1)*.52),w.color,angle));emit(p.x+Math.cos(angle)*40,p.y+Math.sin(angle)*40,w.color,8,90)}slot.cool=w.rate/p.attackSpeed/Math.pow(1.09,level-1);sound(280,.045,'triangle',.012);continue}
if(dist>w.range+40)continue;const bullets=w.pellets+(slot.id==='shotgun'&&level>=3?2:0);for(let n=0;n<bullets;n++){const a=angle+rand(-w.spread,w.spread),speed=w.projectile*(slot.id==='flame'?rand(.8,1.1):1),crit=Math.random()<p.crit,damage=w.damage*(p.damage/10)*(1+(level-1)*.43)*(crit?2:1);game.bullets.push({x:p.x+Math.cos(a)*16,y:p.y+Math.sin(a)*16,vx:Math.cos(a)*speed,vy:Math.sin(a)*speed,r:slot.id==='flame'?7:4,damage,life:w.range/speed,color:w.color,crit,flame:slot.id==='flame',pierce:slot.id==='smg'&&level>=4?1:0})}slot.cool=w.rate/p.attackSpeed/Math.pow(1.1,level-1);sound(slot.id==='shotgun'?175:slot.id==='flame'?320:slot.id==='smg'?540:460,slot.id==='shotgun'?.09:.035,slot.id==='shotgun'?'square':'sine',slot.id==='shotgun'?.025:.009)}}
function hitEnemy(e,damage,color,angle=0){if(e.hp<=0)return;e.hp-=damage;e.flash=.1;e.knock=5;game.shake=Math.max(game.shake,1.6);if(Math.random()<.35||damage>35)floatText(e.x+rand(-5,5),e.y-e.r,`${Math.round(damage)}${damage>=30?'!':''}`,damage>=30?'#ffe17a':'#fff',damage>=30?14:11);emit(e.x,e.y,color,3,65);if(e.hp<=0){game.kills++;const def=ENEMY_TYPES[e.type];game.coinsDrop.push({x:e.x,y:e.y,r:6,kind:'coin',value:def.coins});game.coinsDrop.push({x:e.x+rand(-8,8),y:e.y+rand(-8,8),r:e.type==='boss'?7:5,kind:'xp',value:def.xp});if(e.type==='boss'){for(let i=0;i<8;i++)game.coinsDrop.push({x:e.x+rand(-30,30),y:e.y+rand(-30,30),r:6,kind:'coin',value:3})}emit(e.x,e.y,e.color,e.type==='boss'?35:10,150);sound(200,.04,'triangle',.01)}}
function update(dt){if(state!=='playing'||!game)return;const p=game.player;dt=Math.min(dt,.04);game.elapsed+=dt;game.waveTime-=dt;game.time+=dt;p.invuln=Math.max(0,p.invuln-dt);p.hp=Math.min(p.maxHp,p.hp+p.regen*dt);game.shake=Math.max(0,game.shake-dt*20);
let mx=joy.dx+(keys.d||keys.arrowright?1:0)-(keys.a||keys.arrowleft?1:0),my=joy.dy+(keys.s||keys.arrowdown?1:0)-(keys.w||keys.arrowup?1:0),ml=Math.hypot(mx,my);if(ml>1){mx/=ml;my/=ml}p.x+=mx*p.speed*dt;p.y+=my*p.speed*dt;
game.spawn-=dt;if(game.spawn<=0){let types=['chaser','chaser','fast'];if(game.wave>=2)types.push('tank');if(game.wave>=3)types.push('shooter');if(game.wave>=4)types.push('exploder');spawnEnemy(choice(types));game.spawn=Math.max(.16,.88-(game.wave-1)*.055)}if(game.wave===10&&!game.bossSpawned&&game.waveTime<27){spawnEnemy('boss');game.bossSpawned=true;showToast('⚠ THE STAR DEVOURER')}
