async page => {
  const errors = [];
  page.on('pageerror', e => errors.push(e.message));
  page.on('console', m => { if (m.type() === 'error') errors.push(m.text()); });
  await page.route('**/*', async route => {
    const response = await route.fetch();
    if (route.request().isNavigationRequest()) {
      let body = await response.text();
      body = body.replace('menu();\nconst keys=', `window.__test={get:()=>({state,game}),setCoins:n=>game.player.coins=n,setWave:(n,t=30)=>{game.wave=n;game.waveTime=t},tick:dt=>update(dt),grant:()=>grantXp(game.player.xpNeed-game.player.xp),boss:()=>{game.wave=10;game.waveTime=26.99;game.spawn=100;update(.04)},killBoss:()=>{const b=game.enemies.find(e=>e.type==='boss');if(b)b.hp=0;update(.04)}};\nmenu();\nconst keys=`);
      await route.fulfill({ response, body });
    } else await route.continue();
  });
  await page.setViewportSize({width:390,height:844});
  await page.goto('http://localhost:3002');
  await page.getByRole('button', {name:/DROP IN/}).click();
  const start = await page.evaluate(() => window.__test.get().state);
  await page.evaluate(() => { window.__test.setCoins(100); window.__test.setWave(1, .01); window.__test.tick(.04); });
  const shop = await page.evaluate(() => ({state:window.__test.get().state, wave:window.__test.get().game.wave, items:document.querySelectorAll('[data-buy]').length, text:document.querySelector('#panel').innerText}));
  await page.locator('#lock').click();
  const lockedBefore = await page.locator('[data-buy]').allTextContents();
  await page.locator('#reroll').click();
  const lockedAfter = await page.locator('[data-buy]').allTextContents();
  const locked = await page.locator('#lock').innerText();
  await page.locator('[data-buy]').first().click();
  const afterBuy = await page.evaluate(() => window.__test.get().game.player.coins);
  await page.locator('#next').click();
  const afterNext = await page.evaluate(() => window.__test.get().state);
  await page.evaluate(() => window.__test.grant());
  const level = {state:await page.evaluate(() => window.__test.get().state), choices:await page.locator('[data-up]').count()};
  await page.locator('[data-up]').first().click();
  const afterLevel = await page.evaluate(() => window.__test.get().state);
  await page.evaluate(() => window.__test.boss());
  const boss = await page.evaluate(() => ({state:window.__test.get().state, wave:window.__test.get().game.wave, boss:window.__test.get().game.enemies.some(e=>e.type==='boss')}));
  await page.evaluate(() => window.__test.killBoss());
  const victory = {state:await page.evaluate(() => window.__test.get().state), text:await page.locator('#panel').innerText()};
  console.log(JSON.stringify({start,shop,lockedBefore,lockedAfter,locked,afterBuy,afterNext,level,afterLevel,boss,victory,errors},null,2));
}

